//! Comprehensive cross-validation against R EValue package golden output.
//!
//! Golden values generated by `tests/gen_r_golden.R` using the real R
//! EValue package (v4.1.4). Run:
//! ```sh
//! Rscript tests/gen_r_golden.R tests/evalue_golden.json
//! ```
//! then:
//! ```sh
//! cargo test -p evalue --test cross_validation
//! ```

use evalue::{
    bias_spec, evalue as ev, multi_bound, multi_evalue, selection,
};
use serde_json::Value;

const TOL: f64 = 1e-4;

fn load_golden() -> Value {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/evalue_golden.json");
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| {
        panic!(
            "Failed to read {}: {}. Run `Rscript tests/gen_r_golden.R tests/evalue_golden.json` first.",
            path.display(), e
        )
    });
    serde_json::from_str(&text).expect("Failed to parse golden JSON")
}

/// Extract a numeric field from JSON, handling R's "NA" string.
fn jnum(v: &Value, key: &str) -> Option<f64> {
    let val = &v[key];
    if val.is_null() {
        return None;
    }
    if let Some(s) = val.as_str() {
        if s == "NA" {
            return None;
        }
        return s.parse().ok();
    }
    val.as_f64()
}

// ═══════════════════════════════════════════════════════════════════════
// Simple E-value cross-validation
// ═══════════════════════════════════════════════════════════════════════

#[test]
fn xval_rr_leukemia() {
    let g = load_golden();
    let r = &g["rr_leukemia"];
    let res = ev::evalues_rr(0.80, Some(0.71), Some(0.91), 1.0).unwrap();

    assert!((res.point_evalue().unwrap() - jnum(r, "point_e").unwrap()).abs() < TOL);
    // est < true → upper CI E-value reported
    assert!(
        (res.evalues[2].unwrap() - jnum(r, "upper_e").unwrap()).abs() < TOL,
        "upper E-value mismatch"
    );
}

