#[test]
fn xval_smoking_twoxtwo() {
    let g = load_golden();
    let r = &g["smoking"];
    let (rr, lower, upper) = ev::two_by_two_rr(397.0, 78557.0, 51.0, 108778.0, 0.05);
    let res = ev::evalues_rr(rr, Some(lower), Some(upper), 1.0).unwrap();
    assert!((res.point_evalue().unwrap() - jnum(r, "point_e").unwrap()).abs() < TOL);
}

#[test]
fn xval_rd_smoking() {
    let g = load_golden();
    let r = &g["rd_smoking"];
    let (est_e, lo_e) = ev::evalues_rd(397.0, 78557.0, 51.0, 108778.0, 0.0, 0.05, 0.0001).unwrap();
    assert!((est_e - jnum(r, "est_evalue").unwrap()).abs() < TOL, "est_e: {est_e}");
    assert!((lo_e - jnum(r, "lower_evalue").unwrap()).abs() < TOL, "lower_e: {lo_e}");
}

